import React, { useState, useEffect } from 'react';
import { UniverseTemplate, CharacterTemplate } from '../../types';

interface AdventureLauncherProps {
  universes: UniverseTemplate[];
  characters: CharacterTemplate[];
  onStartAdventure: (universe: UniverseTemplate, character: CharacterTemplate, planetLocation: string) => void;
  onCancel: () => void;
}

const AdventureLauncher: React.FC<AdventureLauncherProps> = ({ universes, characters, onStartAdventure, onCancel }) => {
  const [selectedUniverse, setSelectedUniverse] = useState<string | null>(null);
  const [selectedCharacter, setSelectedCharacter] = useState<string | null>(null);

  // World Selection
  const [worldMode, setWorldMode] = useState<'EXISTING' | 'NEW'>('EXISTING');
  const [selectedWorldName, setSelectedWorldName] = useState<string>('');
  const [newWorldName, setNewWorldName] = useState('');

  const getUniverse = (id: string) => universes.find(u => u.id === id);
  const getCharacter = (id: string) => characters.find(c => c.id === id);

  const activeUniverse = selectedUniverse ? getUniverse(selectedUniverse) : null;

  // Filter Characters based on selected universe (Database Separation)
  const availableCharacters = characters.filter(c => {
      // 1. Characters with NO homeUniverseId are Multiversal (available everywhere)
      if (!c.homeUniverseId) return true;
      // 2. Characters WITH homeUniverseId only show if that universe is selected
      return c.homeUniverseId === selectedUniverse;
  });

  // Reset logic
  useEffect(() => {
    setWorldMode('EXISTING');
    setSelectedWorldName('');
    setNewWorldName('');
    // If current selected character is not valid for the new universe, deselect them
    if (selectedCharacter) {
        const char = characters.find(c => c.id === selectedCharacter);
        if (char && char.homeUniverseId && char.homeUniverseId !== selectedUniverse) {
            setSelectedCharacter(null);
        }
    }
  }, [selectedUniverse]);

  const handleStart = () => {
    const finalLocation = worldMode === 'EXISTING' ? selectedWorldName : newWorldName;

    if (selectedUniverse && selectedCharacter && finalLocation.trim()) {
      const u = getUniverse(selectedUniverse);
      const c = getCharacter(selectedCharacter);
      if (u && c) onStartAdventure(u, c, finalLocation);
    }
  };

  return (
    <div className="flex-1 flex flex-col p-6 bg-stone-950 animate-fade-in overflow-y-auto pb-24">
      <div className="max-w-6xl w-full mx-auto space-y-8">

        <header className="flex flex-col md:flex-row items-start md:items-end justify-between border-b border-stone-900 pb-4 gap-4">
            <div>
                <h2 className="text-4xl font-serif text-stone-200 tracking-tight">O Nexus</h2>
                <p className="text-stone-600 text-xs uppercase tracking-widest mt-2">Selecione o Container (Universo) e a Alma (Personagem) para iniciar.</p>
            </div>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

             {/* COLUMN 1: UNIVERSE SELECTION (CONTAINER) - MOVED FIRST FOR DATABASE LOGIC */}
             <div className="lg:col-span-4 space-y-4 flex flex-col h-full border-r border-stone-900 pr-8">
                <h3 className="text-amber-900 text-[10px] uppercase tracking-widest border-b border-stone-900 pb-2">1. Escolha o Banco de Dados (Universo)</h3>
                <div className="space-y-3 flex-1 overflow-y-auto max-h-[500px] custom-scrollbar pr-2">
                    {universes.length === 0 && (
                        <div className="p-8 border border-dashed border-stone-800 text-center text-stone-600 text-xs italic">
                            Nenhum universo encontrado.<br/>Crie um na biblioteca.
                        </div>
                    )}
                    {universes.map(u => (
                        <button
                            key={u.id}
                            onClick={() => setSelectedUniverse(u.id)}
                            className={`w-full text-left p-4 rounded-sm border transition-all ${
                                selectedUniverse === u.id 
                                ? 'bg-stone-800 border-stone-600' 
                                : 'bg-stone-900/30 border-stone-800 hover:bg-stone-900'
                            }`}
                        >
                            <div className="flex justify-between mb-1">
                                <span className={`font-serif text-lg ${selectedUniverse === u.id ? 'text-stone-200' : 'text-stone-400'}`}>
                                    {u.name}
                                </span>
                            </div>
                            <p className="text-stone-500 text-xs line-clamp-2">{u.description}</p>

                            <div className="mt-3 flex gap-2 flex-wrap">
                                {(u.chronicles && u.chronicles.length > 0) && (
                                    <span className="text-[9px] bg-stone-950 text-cyan-600 border border-stone-800 px-1.5 py-0.5 rounded flex items-center gap-1">
                                        ⏳ {u.chronicles.length} Eventos Históricos
                                    </span>
                                )}
                            </div>
                        </button>
                    ))}
                </div>
            </div>

            {/* COLUMN 2: CHARACTER SELECTION (SOUL) */}
            <div className="lg:col-span-3 space-y-4 flex flex-col h-full pl-2">
                <h3 className="text-amber-900 text-[10px] uppercase tracking-widest border-b border-stone-900 pb-2">2. Escolha a Alma</h3>

                {!selectedUniverse ? (
                    <div className="p-4 text-stone-700 text-xs italic border border-dashed border-stone-900">
                        Selecione um Universo primeiro para ver os habitantes disponíveis.
                    </div>
                ) : (
                    <div className="space-y-3 flex-1 overflow-y-auto max-h-[500px] custom-scrollbar">
                        {availableCharacters.length === 0 && (
                             <div className="p-4 text-stone-700 text-xs italic border border-dashed border-stone-900">
                                Nenhuma alma encontrada neste universo.
                             </div>
                        )}
                        {availableCharacters.map(c => (
                            <button
                                key={c.id}
                                onClick={() => setSelectedCharacter(c.id)}
                                className={`w-full text-left p-3 rounded-sm border transition-all ${
                                    selectedCharacter === c.id 
                                    ? 'bg-amber-900/20 border-amber-700' 
                                    : 'bg-stone-900/30 border-stone-800 hover:bg-stone-900'
                                }`}
                            >
                                <div className="flex justify-between mb-1">
                                    <span className={`font-serif text-sm ${selectedCharacter === c.id ? 'text-amber-500' : 'text-stone-300'}`}>
                                        {c.name}
                                    </span>
                                    {(c.adventuresPlayed || 0) > 0 && (
                                        <span className="text-[9px] text-stone-500" title="Aventuras jogadas">
                                        ↺ {c.adventuresPlayed}
                                        </span>
                                    )}
                                </div>
                                <div className="flex justify-between items-center">
                                    <span className="text-[9px] uppercase tracking-wider text-stone-600 border border-stone-800 px-1 rounded">
                                        {c.archetype}
                                    </span>
                                    {c.homeUniverseId ? (
                                        <span className="text-[9px] text-emerald-700 font-bold" title="Nativo deste universo">⌂ Nativo</span>
                                    ) : (
                                        <span className="text-[9px] text-stone-600" title="Multiversal">∞ Viajante</span>
                                    )}
                                </div>
                            </button>
                        ))}
                    </div>
                )}
            </div>

            {/* COLUMN 3: PERSISTENT CONTEXT (HISTORY & WORLD) */}
            <div className="lg:col-span-5 space-y-6 bg-stone-900/10 p-6 border border-stone-900/50 rounded-sm">
                 {activeUniverse ? (
                     <div className="space-y-6 animate-fade-in">

                        {/* Universe Header */}
                        <div>
                            <h3 className="text-2xl font-serif text-stone-300">{activeUniverse.name}</h3>
                            <span className="text-[10px] text-stone-500 uppercase tracking-widest">{activeUniverse.cosmology || 'Cosmologia Desconhecida'}</span>
                        </div>

                        {/* PERSISTENT HISTORY LOG */}
                        <div className="bg-stone-950 p-4 rounded border border-stone-800 max-h-40 overflow-y-auto custom-scrollbar">
                            <h4 className="text-[10px] text-cyan-800 uppercase tracking-widest mb-3 sticky top-0 bg-stone-950 pb-2 border-b border-stone-900">
                                Memória Universal (Persistente)
                            </h4>
                            {activeUniverse.chronicles && activeUniverse.chronicles.length > 0 ? (
                                <ul className="space-y-3">
                                    {activeUniverse.chronicles.map((event, i) => (
                                        <li key={i} className="flex gap-3 text-xs">
                                            <span className="text-stone-500 font-mono whitespace-nowrap">[{event.year}]</span>
                                            <span className="text-stone-400">{event.event}</span>
                                        </li>
                                    ))}
                                </ul>
                            ) : (
                                <p className="text-stone-700 italic text-xs">Este universo ainda é virgem. Nenhuma história foi escrita.</p>
                            )}
                        </div>

                        <div className="h-px bg-stone-800 w-full"></div>

                        {/* World Picker */}
                        <div className="space-y-4">
                             <h3 className="text-amber-900 text-[10px] uppercase tracking-widest">3. Defina o Ponto de Entrada (Mundo)</h3>

                             <div className="flex gap-2 bg-stone-950 p-1 rounded border border-stone-800">
                                <button 
                                    onClick={() => setWorldMode('EXISTING')}
                                    className={`flex-1 py-2 text-[10px] uppercase tracking-wider rounded-sm transition-colors ${worldMode === 'EXISTING' ? 'bg-stone-800 text-amber-500' : 'text-stone-600 hover:text-stone-400'}`}
                                >
                                    Mundos Conhecidos
                                </button>
                                <button 
                                    onClick={() => setWorldMode('NEW')}
                                    className={`flex-1 py-2 text-[10px] uppercase tracking-wider rounded-sm transition-colors ${worldMode === 'NEW' ? 'bg-stone-800 text-emerald-500' : 'text-stone-600 hover:text-stone-400'}`}
                                >
                                    Novo Setor
                                </button>
                             </div>

                             {worldMode === 'EXISTING' ? (
                                <div className="space-y-2">
                                    {activeUniverse.worlds && activeUniverse.worlds.length > 0 ? (
                                        <div className="grid gap-2">
                                            {activeUniverse.worlds.map((w, idx) => (
                                                <button
                                                    key={idx}
                                                    onClick={() => setSelectedWorldName(w.name)}
                                                    className={`text-left p-3 border rounded-sm transition-colors ${selectedWorldName === w.name ? 'border-amber-600 bg-amber-900/10' : 'border-stone-800 bg-stone-900/50 hover:bg-stone-900'}`}
                                                >
                                                    <div className="text-sm font-serif text-stone-300">{w.name}</div>
                                                    <div className="text-[10px] text-stone-500 truncate">{w.description}</div>
                                                </button>
                                            ))}
                                        </div>
                                    ) : (
                                        <div className="text-center py-6 text-stone-600 text-xs italic">
                                            Nenhum mundo registrado.<br/>Crie o primeiro ponto de entrada.
                                        </div>
                                    )}
                                </div>
                             ) : (
                                <div className="space-y-2 animate-fade-in">
                                    <input 
                                        type="text"
                                        value={newWorldName}
                                        onChange={(e) => setNewWorldName(e.target.value)}
                                        placeholder="Nome do Novo Local..."
                                        className="w-full bg-stone-950 border-b border-stone-700 py-3 text-stone-200 focus:border-emerald-600 focus:outline-none transition-colors"
                                    />
                                </div>
                             )}
                        </div>

                     </div>
                 ) : (
                     <div className="h-full flex items-center justify-center text-stone-700 text-sm italic">
                         Selecione o Universo para ver sua história e mundos.
                     </div>
                 )}
            </div>

        </div>

        {/* START BUTTON */}
        <div className="pt-8 border-t border-stone-900 text-center">
            <button
                onClick={handleStart}
                disabled={!selectedUniverse || !selectedCharacter || (!selectedWorldName && !newWorldName)}
                className="px-16 py-5 bg-stone-100 text-stone-950 font-serif tracking-widest uppercase hover:bg-amber-500 transition-colors disabled:opacity-20 disabled:cursor-not-allowed shadow-[0_0_20px_rgba(255,255,255,0.1)] text-lg"
            >
                Materializar
            </button>
        </div>

      </div>
    </div>
  );
};

