import { useState, useEffect } from 'react';
import { useGameEngine } from './useGameEngine';
import { usePersistence } from './usePersistence';
import { useLibrary } from './useLibrary';
import { checkBackendHealth } from '../services/ragService';
import { NavTab } from '../components/BottomNav';
import { UniverseTemplate, CharacterTemplate } from '../types';

export type ViewState = 'ADVENTURE_LAUNCHER' | 'ADVENTURE_LIST' | 'UNIVERSE_LIST' | 'UNIVERSE_CREATOR' | 'CHARACTER_LIST' | 'CHARACTER_CREATOR' | 'SETTINGS' | 'GAME';

export const useAppController = () => {
  const [hasApiKey, setHasApiKey] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isInvestigationMode, setIsInvestigationMode] = useState(false);
  const [currentView, setCurrentView] = useState<ViewState>('ADVENTURE_LAUNCHER');
  const [backendStatus, setBackendStatus] = useState<'checking' | 'online' | 'offline'>('checking');

  // Library & Persistence
  const { universes, characters, addUniverse, addCharacter, restoreDefaults, evolveUniverse, trackCharacterUsage, addAdventureRecord } = useLibrary();
  const { saveGame, parseSaveFile } = usePersistence();

  // Game Engine
  const { gameState, isProcessing, startGame, performAction, resetGame, restoreGame } = useGameEngine(evolveUniverse);

  // --- Effects ---

  // Auto-open sidebar on game start
  useEffect(() => {
    if (gameState && currentView === 'GAME') {
      setIsSidebarOpen(true);
    }
  }, [gameState, currentView]);

  // Check Backend Health when entering Settings
  useEffect(() => {
    if (currentView === 'SETTINGS') {
      setBackendStatus('checking');
      checkBackendHealth().then(isOnline => {
        setBackendStatus(isOnline ? 'online' : 'offline');
      });
    }
  }, [currentView]);

  // --- Handlers ---

  const handleStartAdventure = (u: UniverseTemplate, c: CharacterTemplate) => {
    trackCharacterUsage(c.id);
    addAdventureRecord(u, c);

    const physicsBlock = u.physics && u.physics.length > 0 ? `LEIS DA REALIDADE (Imutáveis):\n${u.physics.map(p=>`- ${p}`).join('\n')}` : '';
    const truthsBlock = u.knownTruths && u.knownTruths.length > 0 ? `VERDADES DESCOBERTAS (Conhecimento Acumulado):\n${u.knownTruths.map(t=>`- ${t}`).join('\n')}` : '';
    const timelineBlock = u.chronicles && u.chronicles.length > 0 ? `CRONOLOGIA CANÔNICA DO UNIVERSO (HISTÓRICO COMPARTILHADO):\n${u.chronicles.map(t=>`[${t.year}] ${t.event}`).join('\n')}` : '';
    const legendsBlock = u.champions && u.champions.length > 0 ? `LENDAS E HERÓIS PASSADOS:\n${u.champions.map(ch => `- ${ch.characterName}: ${ch.feat} (${ch.status})`).join('\n')}` : '';
    const magicBlock = u.magicSystem ? `SISTEMA DE MAGIA/TECNOLOGIA: ${u.magicSystem}` : '';

    const structureLabel = u.structure === 'star_cluster' ? "AGLOMERADO ESTELAR (Viagem entre Planetas)" : u.structure === 'singular_world' ? "PLANETA ÚNICO/INFINITO (Viagem Regional)" : "NEXUS MULTIVERSAL";
    const navLabel = u.navigationMethod === 'interstellar_ship' ? "NAVES ESPACIAIS" : u.navigationMethod === 'magical_gate' ? "PORTAIS MÁGICOS" : "FÍSICA (Caminhada/Veículos)";

    const settingInstruction = `
    DECISÃO DO MESTRE DE JOGO NECESSÁRIA:
    O jogador não especificou um local de início.
    Com base no Arquétipo do personagem (${c.archetype}) e no Gênero do Universo (${u.genre}), escolha um local inicial dramático e apropriado.
    `;

    const fullSettingContext = `
      UNIVERSE CONTAINER: ${u.name} (${u.genre})
      ESTRUTURA FÍSICA: ${structureLabel}
      MÉTODO DE VIAGEM PREDOMINANTE: ${navLabel}
      DESCRIÇÃO DO UNIVERSO: ${u.description}
      COSMOLOGIA: ${u.cosmology || 'Desconhecida'}
      ${physicsBlock}
      ${magicBlock}
      ${truthsBlock}
      ${timelineBlock}
      ${legendsBlock}
      ---
      STARTING INSTRUCTION: ${settingInstruction}
      ---
    `;

    startGame(c, fullSettingContext, u.id, u.name);
    setCurrentView('GAME');
  };

  const handleLoadGame = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const loadedState = await parseSaveFile(file);
      restoreGame(loadedState);
      setCurrentView('GAME');
    } catch (err) {
      console.error(err);
      alert("Arquivo de save inválido ou corrompido.");
    }
  };

  const handleExitToHub = () => {
    resetGame();
    setCurrentView('ADVENTURE_LAUNCHER');
  };

  const getActiveTab = (): NavTab => {
    if (currentView === 'ADVENTURE_LIST') return 'ADVENTURES';
    if (currentView === 'UNIVERSE_LIST' || currentView === 'UNIVERSE_CREATOR') return 'UNIVERSES';
    if (currentView === 'CHARACTER_LIST' || currentView === 'CHARACTER_CREATOR') return 'CHARACTERS';
    if (currentView === 'SETTINGS') return 'SETTINGS';
    return 'PLAY';
  };

  const handleTabChange = (tab: NavTab) => {
    switch (tab) {
      case 'PLAY': setCurrentView('ADVENTURE_LAUNCHER'); break;
      case 'ADVENTURES': setCurrentView('ADVENTURE_LIST'); break;
      case 'UNIVERSES': setCurrentView('UNIVERSE_LIST'); break;
      case 'CHARACTERS': setCurrentView('CHARACTER_LIST'); break;
      case 'SETTINGS': setCurrentView('SETTINGS'); break;
    }
  };

  return {
    state: {
      hasApiKey,
      isSidebarOpen,
      isInvestigationMode,
      currentView,
      backendStatus,
      gameState,
      isProcessing,
      universes,
      characters
    },
    actions: {
      setHasApiKey,
      setIsSidebarOpen,
      setIsInvestigationMode,
      setCurrentView,
      addUniverse,
      addCharacter,
      restoreDefaults,
      performAction,
      saveGame,
      handleStartAdventure,
      handleLoadGame,
      handleExitToHub,
      handleTabChange
    },
    computed: {
      activeTab: getActiveTab()
    }
  };
};

import React from 'react';
import ApiKeyModal from './components/ApiKeyModal';

// Architecture
import { useAppController } from './hooks/useAppController';
import GameLayout from './components/layouts/GameLayout';

// Screens
import GameScreen from './components/screens/GameScreen';
import SettingsScreen from './components/screens/SettingsScreen';
import AdventureLauncher from './components/creators/AdventureLauncher';
import { UniverseList, CharacterList, AdventureList } from './components/library/LibraryViews';
import UniverseCreator from './components/creators/UniverseCreator';
import CharacterCreator from './components/creators/CharacterCreator';

function App() {
  const { state, actions, computed } = useAppController();

  if (!state.hasApiKey) {
    return <ApiKeyModal onKeySelected={() => actions.setHasApiKey(true)} />;
  }

  return (
    <GameLayout
      gameState={state.gameState}
      currentView={state.currentView}
      isSidebarOpen={state.isSidebarOpen}
      activeTab={computed.activeTab}
      onToggleSidebar={() => actions.setIsSidebarOpen(!state.isSidebarOpen)}
      onReset={actions.handleExitToHub}
      onSave={() => actions.saveGame(state.gameState)}
      onLoad={actions.handleLoadGame}
      onTabChange={actions.handleTabChange}
    >

      {/* --- ROUTING --- */}

      {state.currentView === 'ADVENTURE_LAUNCHER' && (
        <AdventureLauncher 
          universes={state.universes}
          characters={state.characters}
          onStartAdventure={actions.handleStartAdventure}
          onCancel={() => {}} 
        />
      )}

      {state.currentView === 'ADVENTURE_LIST' && (
        <AdventureList onLoadGame={actions.handleLoadGame} />
      )}

      {state.currentView === 'UNIVERSE_LIST' && (
        <UniverseList onCreate={() => actions.setCurrentView('UNIVERSE_CREATOR')} />
      )}
      {state.currentView === 'UNIVERSE_CREATOR' && (
        <UniverseCreator 
          onSave={(t) => { actions.addUniverse(t); actions.setCurrentView('UNIVERSE_LIST'); }} 
          onCancel={() => actions.setCurrentView('UNIVERSE_LIST')} 
        />
      )}

      {state.currentView === 'CHARACTER_LIST' && (
        <CharacterList onCreate={() => actions.setCurrentView('CHARACTER_CREATOR')} />
      )}
      {state.currentView === 'CHARACTER_CREATOR' && (
        <CharacterCreator 
          onSave={(t) => { actions.addCharacter(t); actions.setCurrentView('CHARACTER_LIST'); }} 
          onCancel={() => actions.setCurrentView('CHARACTER_LIST')}
        />
      )}

      {state.currentView === 'SETTINGS' && (
         <SettingsScreen 
            backendStatus={state.backendStatus}
            onRestoreDefaults={() => { if(confirm('Restaurar templates?')) { actions.restoreDefaults(); alert('Restaurado!'); window.location.reload(); } }}
            onFactoryReset={() => { if(confirm('Limpar TUDO?')) { localStorage.clear(); window.location.reload(); } }}
         />
      )}

      {state.currentView === 'GAME' && (
        <GameScreen 
          gameState={state.gameState}
          isProcessing={state.isProcessing}
          isInvestigationMode={state.isInvestigationMode}
          onPerformAction={actions.performAction}
          onToggleMode={() => actions.setIsInvestigationMode(!state.isInvestigationMode)}
        />
      )}

    </GameLayout>
  );
}

export default App;

// --- Game State Types (The "Adventure State" - Volatile) ---

export interface KnowledgeEntry {
  id: string; // Name or unique identifier
  type: 'character' | 'location' | 'lore';
  description: string;
  status?: string; // e.g., "Ally", "Enemy", "Visited", "Unknown"
}

export interface QuestEntry {
  id: string;
  title: string;
  description: string;
  status: 'active' | 'completed' | 'failed';
}

export interface NPCEntity {
  id: string; 
  name: string; 
  descriptor: string; 
  isNameKnown: boolean; 
  location: string;
  action: string; 
  lastThought: string; 
  status: string; 
}

export interface GraphEdge {
  subject: string;
  relation: string;
  object: string;
  properties?: Record<string, any>;
}

export interface PlayerStats {
  strength: number;
  agility: number;
  intelligence: number;
  spirit: number;
  health: number;
  maxHealth: number;
}

export interface GameState {
  universeId: string; // Link to the "Stage"
  userId?: string;    // Link to the "User/Owner"

  player: {
    sourceId: string; // Link to the "Soul/Identity" (CharacterTemplate ID)
    name: string;     // Can change in-game (alias), but defaults to Template name
    description: string; // Current physical state description
    inventory: string[];
    status: string;
    location: string;
    stats: PlayerStats; 
  };
  world: {
    time: string;
    weather: string;
    activeEvents: string[];
    npcs: NPCEntity[];
  };
  knowledgeBase: {
    characters: KnowledgeEntry[];
    locations: KnowledgeEntry[];
    lore: KnowledgeEntry[];
    quests: QuestEntry[];
  };
  summary: string; 
  history: ChatEntry[];
}

export interface ChatEntry {
  role: 'user' | 'model' | 'system';
  text: string;
  simulationData?: SimulationResponse; 
  type?: 'action' | 'investigation' | 'debug';
}

// --- Library Templates (The "Identity" & "Cosmos" - Permanent) ---

export interface TimelineEvent {
  year: string;
  event: string;
  era?: string;
}

export interface ChampionRecord {
  characterName: string;
  feat: string;
  date: string; // Real world date or Game date
  status: 'Legend' | 'Myth' | 'Forgotten';
}

export interface WorldEntry {
    name: string;
    description: string;
}

export interface AdventureRecord {
  id: string;
  characterName: string;
  universeName: string;
  universeGenre: string;
  startDate: number;
  lastLocation?: string; // Optional metadata
}

export type UniverseStructure = 'singular_world' | 'star_cluster' | 'multiverse_hub';
export type NavigationMethod = 'physical' | 'interstellar_ship' | 'magical_gate' | 'dream_walking';

export interface UniverseTemplate {
  id: string;
  name: string; // Ex: "Dimensão C-137" ou "O Multiverso de Aether"
  description: string; // Descrição geral do "Vibe"
  genre: string;
  createdAt: number;

  // V2: Deep Universe Properties
  structure: UniverseStructure; // NOVO: Define se é Planeta Infinito ou Galáxia
  navigationMethod: NavigationMethod; // NOVO: Define como se viaja entre os "Wolds"
  physics: string[]; // Leis fundamentais (Hard Rules)
  magicSystem: string; 
  cosmology: string; // Estrutura do universo (Ex: "9 Reinos", "Galáxia Espiral", "Terra Plana Infinita")

  // V3: Living Database
  knownTruths: string[]; 
  chronicles: TimelineEvent[]; // História do Universo (não de um planeta só)
  champions: ChampionRecord[]; 
  worlds: WorldEntry[]; // Lista de Planetas/Reinos descobertos onde as tramas ocorrem
}

export interface CharacterTemplate {
  // Identity (The Actor)
  id: string;
  name: string;
  description: string; // The "essence" or core personality
  archetype: string;   // The preferred "role" they play

  // Meta-Progression
  adventuresPlayed?: number; // Tracks usage across all stages
  createdAt: number;
}

// --- AI Response Types ---

export interface WorldUpdate {
  actionResult: string;
  playerStatus: string;
  newLocation: string;
  timePassed: string;
  currentWeather: string;
  worldEvents: string[];
  inventoryUpdates: {
    added?: string[];
    removed?: string[];
  };
  statChanges?: Partial<PlayerStats>;
}

export interface NPCBehaviorResponse {
  npcs: NPCEntity[];
}

export interface NarrativeResponse {
  narrative: string;
  canonicalEvents?: string[]; 
  discoveredTruths?: string[]; 
  graphUpdates?: GraphEdge[];
  knowledgeUpdate?: {
    characters?: KnowledgeEntry[];
    locations?: KnowledgeEntry[];
    lore?: KnowledgeEntry[];
    quests?: QuestEntry[];
  };
}

export interface SimulationResponse extends NarrativeResponse {
  worldUpdate: WorldUpdate;
  npcSimulation: NPCEntity[];
  initialTime?: string;
}

import { GameState, GraphEdge } from "../types";

// --- RAG & TRIPLE STORE CLIENT SERVICE ---
// Este serviço conecta o frontend React ao servidor Python Backend.
const SERVER_URL = "https://6b10889bffdd.ngrok-free.app";

export interface RagDocument {
  page_content: string;
  metadata: any;
}

// Payload unificado para envio aos 3 servidores de uma vez
export interface UnifiedIngestPayload {
  userId: string; // NOVO: Identificação do usuário proprietário dos dados
  universeId: string;
  turnId: number;
  timestamp: string; // Game Time

  // 1. CHROMA DB (Semantic)
  vectorData: {
    text: string;
    type: 'turn' | 'lore' | 'intro';
    location: string;
  };

  // 2. SQLITE (Structured Log)
  sqlData: {
    playerStatus: any;
    inventory: string[];
    worldState: any;
  };

  // 3. NEO4J (Graph Relations)
  graphData: GraphEdge[];
}

/**
 * Envia o Snapshot completo do turno para o Backend.
 * O Backend Python deve rotear cada parte para seu DB específico.
 */
export const ingestUnifiedMemory = async (payload: UnifiedIngestPayload) => {
  try {
    const response = await fetch(`${SERVER_URL}/ingest/unified`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
        console.warn("Triple Store Ingest Error:", response.statusText);
    }
  } catch (error) {
    console.debug("Backend offline (Ingest skipped).");
  }
};

/**
 * Busca memórias relevantes (Vector Search) ESPECÍFICAS DE UM UNIVERSO E USUÁRIO.
 */
export const retrieveContext = async (query: string, universeId: string, userId: string): Promise<string[]> => {
  try {
    const response = await fetch(`${SERVER_URL}/query`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
          query: query,
          universeId: universeId, // Partition Key 1
          userId: userId          // Partition Key 2
      })
    });

    if (!response.ok) return [];

    const data = await response.json();
    return data.documents || [];
  } catch (error) {
    return [];
  }
};

/**
 * Verifica se o servidor backend está online.
 */
export const checkBackendHealth = async (): Promise<boolean> => {
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 2000);

    // Tenta pingar a raiz ou endpoint de health
    const response = await fetch(`${SERVER_URL}/`, {
      method: 'GET',
      headers: { 'Content-Type': 'application/json' },
      signal: controller.signal
    });

    clearTimeout(timeoutId);
    return response.ok;
  } catch (error) {
    return false;
  }
};

import { GameState, SimulationResponse, NarrativeResponse, WorldUpdate, NPCBehaviorResponse, CharacterTemplate } from "../types";
import { synthesizeNarrative, initializeGameSession } from "./agents/narrator";
import { runNPCBehaviorEngine } from "./agents/npc";
import { runWorldSimulation } from "./agents/world";
import { investigateScene, summarizeMemory, debugSimulation } from "./agents/system";
import { resolveDialogueTags } from "./agents/dialogue";
import { ingestUnifiedMemory, UnifiedIngestPayload } from "./ragService";

// Re-export specific agent functions
export { investigateScene, summarizeMemory, debugSimulation };

// --- PHASE 1: NARRATIVE (Fast, User Facing) ---
export const generateStory = async (
  action: string, 
  currentState: GameState
): Promise<NarrativeResponse> => {
  // 1. Narrator generates story with placeholders [[DIALOGUE:...]]
  // Pass the Universe ID for RAG Context Retrieval
  const rawResponse = await synthesizeNarrative(action, currentState);

  // 2. Dialogue Agent resolves placeholders in parallel
  const finalNarrativeText = await resolveDialogueTags(rawResponse.narrative, currentState);

  // 3. RETURN immediately for UI rendering.
  return {
    ...rawResponse,
    narrative: finalNarrativeText
  };
};

// --- PHASE 2: STATE SYNCHRONIZATION (Background) ---
export const synchronizeState = async (
  action: string,
  narrative: string,
  currentState: GameState,
  narrativeResponse?: NarrativeResponse // Passed to get graph data
): Promise<{ world: WorldUpdate, npcs: NPCBehaviorResponse }> => {

  // Parallel execution of state updaters
  const [worldRes, npcRes] = await Promise.all([
    runWorldSimulation(action, narrative, currentState),
    runNPCBehaviorEngine(currentState, action, narrative)
  ]);

  // --- TRIPLE STORE INGESTION ---
  if (narrativeResponse && currentState.userId) {

      // Calculate snapshot of inventory for logs
      let currentInventory = [...currentState.player.inventory];
      if (worldRes.inventoryUpdates?.added) {
        currentInventory.push(...worldRes.inventoryUpdates.added);
      }
      if (worldRes.inventoryUpdates?.removed) {
        currentInventory = currentInventory.filter(item => !worldRes.inventoryUpdates?.removed?.includes(item));
      }

      const payload: UnifiedIngestPayload = {
          userId: currentState.userId,
          universeId: currentState.universeId,
          turnId: currentState.history.length + 1,
          timestamp: currentState.world.time, 

          // 1. Vector (Chroma)
          vectorData: {
              text: `[ACTION]: ${action}\n[RESULT]: ${narrative}`,
              type: 'turn',
              location: worldRes.newLocation
          },

          // 2. SQL (Logs)
          sqlData: {
              playerStatus: worldRes.playerStatus,
              inventory: currentInventory,
              worldState: {
                  location: worldRes.newLocation,
                  time: worldRes.timePassed,
                  weather: worldRes.currentWeather
              }
          },

          // 3. Graph (Neo4j)
          graphData: narrativeResponse.graphUpdates || []
      };

      // Fire and forget
      ingestUnifiedMemory(payload);

      // Handle specific Lore Canonical Events
      if (narrativeResponse.canonicalEvents && narrativeResponse.canonicalEvents.length > 0) {
          narrativeResponse.canonicalEvents.forEach(event => {
             const lorePayload: UnifiedIngestPayload = {
                 ...payload,
                 vectorData: { ...payload.vectorData, text: event, type: 'lore' },
                 graphData: [] 
             };
             ingestUnifiedMemory(lorePayload);
          });
      }
  }

  return {
    world: worldRes,
    npcs: npcRes
  };
};

export const initializeGame = async (character: CharacterTemplate, setting: string, universeId: string, universeName: string, userId: string): Promise<SimulationResponse> => {
  // 1. Narrator creates initial state, pulling RAG context from the Universe ID
  const rawResponse = await initializeGameSession(character, setting, universeId, universeName, userId);

  // 2. Resolve any initial dialogues (though less likely in intro, it supports it)
  const mockState: GameState = {
    userId: userId,
    universeId: universeId,
    player: { 
        sourceId: character.id,
        name: character.name, 
        description: character.description, 
        inventory: [], 
        status: "", 
        location: "",
        stats: {
            strength: 10,
            agility: 10,
            intelligence: 10,
            spirit: 10,
            health: 100,
            maxHealth: 100
        }
    },
    world: { time: "", weather: "", activeEvents: [], npcs: rawResponse.npcSimulation || [] },
    knowledgeBase: { characters: [], locations: [], lore: [], quests: [] },
    summary: "",
    history: []
  };

  const finalNarrativeText = await resolveDialogueTags(rawResponse.narrative, mockState);

  // Ingest initial LORE if generated
  const payload: UnifiedIngestPayload = {
      userId: userId,
      universeId: universeId,
      turnId: 0,
      timestamp: rawResponse.initialTime || "Start",
      vectorData: {
          text: finalNarrativeText,
          type: 'intro',
          location: "Start"
      },
      sqlData: {
          playerStatus: "Healthy",
          inventory: [],
          worldState: {}
      },
      graphData: rawResponse.graphUpdates || []
  };
  ingestUnifiedMemory(payload);

  return {
    ...rawResponse,
    narrative: finalNarrativeText
  };
};

import { GameState, NarrativeResponse, SimulationResponse, CharacterTemplate } from "../../types";
import { NarrativeSchema, InitSchema } from "../ai/schemas";
import { NARRATOR_INSTRUCTION } from "../ai/prompts";
import { generateContentWithRetry, NARRATOR_MODEL, parseAIResponse } from "../ai/client";
import { getSimulationHistory, getKnowledgeContext } from "../../utils/contextBuilder";
import { retrieveContext } from "../ragService";

// The Narrator is now the FIRST step (The Leader).
// It decides the outcome and writes the story immediately.
export const synthesizeNarrative = async (
  action: string,
  currentState: GameState
): Promise<NarrativeResponse> => {

  // 1. RAG RETRIEVAL (Tenta buscar memórias no servidor Python)
  // Buscamos baseados na ação, localização E HISTÓRIA DO UNIVERSO + USUÁRIO
  const ragQuery = `Action: ${action} | Location: ${currentState.player.location}`;

  // Adicione proteção se userId não existir (ex: saves antigos), use 'guest'
  const userId = currentState.userId || 'guest';
  const longTermMemories = await retrieveContext(ragQuery, currentState.universeId, userId);

  const formattedMemories = longTermMemories.length > 0 
    ? `[MEMÓRIAS E LENDAS RECUPERADAS DO BANCO DE DADOS DO UNIVERSO]:\n${longTermMemories.map(m => `- ${m}`).join('\n')}`
    : "";

  // 2. Filtra NPCs locais
  const presentNPCs = currentState.world.npcs
    .filter(npc => npc.location === currentState.player.location)
    .map(npc => `- ${npc.isNameKnown ? npc.name : npc.descriptor} (Ação: ${npc.action}, Status: ${npc.status})`)
    .join("\n");

  const context = `
  [HISTÓRICO RECENTE]:
  ${getSimulationHistory(currentState.history)}

  ${formattedMemories}

  [CONTEXTO DE CONHECIMENTO (Códex)]:
  ${getKnowledgeContext(currentState.knowledgeBase)}

  [ESTADO ATUAL DO JOGADOR]:
  Local: ${currentState.player.location}
  Status: ${currentState.player.status}
  Inventário: ${currentState.player.inventory.join(", ")}
  Tempo: ${currentState.world.time}

  [PESSOAS PRESENTES NESTE LOCAL (${currentState.player.location})]:
  ${presentNPCs || "Ninguém visível."}
  `;

  const prompt = `
  AÇÃO DO JOGADOR: "${action}"

  TAREFA DE ESCRITA:
  1. Atue como Mestre de Jogo. Decida o resultado lógico da ação.
  2. Use as [MEMÓRIAS E LENDAS RECUPERADAS] para manter a consistência histórica do universo. Se o jogador encontrar uma estátua descrita no RAG, descreva-a conforme os dados recuperados.
  3. Escreva a resposta narrativa em 2ª pessoa usando as tags [[DIALOGUE:...]] para falas.
  4. Se ocorrer algo EPICO que muda a história do mundo, adicione ao campo 'canonicalEvents'.
  `;

  const response = await generateContentWithRetry(NARRATOR_MODEL, {
    contents: context + "\n" + prompt,
    config: {
      systemInstruction: NARRATOR_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: NarrativeSchema,
    }
  });

  return parseAIResponse<NarrativeResponse>(response.text);
};

export const initializeGameSession = async (character: CharacterTemplate, setting: string, universeId: string, universeName: string, userId: string): Promise<SimulationResponse> => {

  // No início, buscamos Lendas Gerais do Universo específico para dar contexto
  const ragQuery = `Overview history legends of universe ${universeName}`;
  const loreContext = await retrieveContext(ragQuery, universeId, userId);

  const formattedLore = loreContext.length > 0 
    ? `[LENDAS E HISTÓRIA DO UNIVERSO (CONTEXTO RAG)]:\n${loreContext.map(m => `- ${m}`).join('\n')}`
    : "";

  const prompt = `
  INICIAR SIMULAÇÃO.

  [CONTAINER / BANCO DE DADOS]:
  Universo: ${universeName} (ID: ${universeId})
  Cenário Inicial da Aventura: ${setting}

  [ALMA / ATOR]:
  Nome: ${character.name}
  Arquétipo: ${character.archetype}
  Backstory/Essência (Imutável): ${character.description}

  ${formattedLore}

  Gere:
  1. Uma DATA e HORA inicial.
  2. A narrativa inicial. Incorpore elementos das [LENDAS] se apropriado, mas foque na materialização do personagem neste cenário.
  3. O estado inicial do mundo.
  4. Os NPCs iniciais.
  `;

  const response = await generateContentWithRetry(NARRATOR_MODEL, {
    contents: prompt,
    config: {
      systemInstruction: NARRATOR_INSTRUCTION + "\nVocê está criando o ESTADO INICIAL de uma nova aventura. Use a Identidade do personagem para moldar como ele percebe o mundo.",
      responseMimeType: "application/json",
      responseSchema: InitSchema,
    }
  }, 6, 3000);

  return parseAIResponse<SimulationResponse>(response.text);
};

