import React, { useState } from 'react';

interface LoginScreenProps {
  onLogin: (userId: string) => void;
}

const LoginScreen: React.FC<LoginScreenProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    setError(null); // Limpa erro ao digitar
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Validação Básica
    if (isRegistering) {
        if (!formData.name || !formData.username || !formData.email || !formData.password) {
            setError("Todos os campos são obrigatórios.");
            return;
        }
        if (formData.password !== formData.confirmPassword) {
            setError("As senhas não coincidem.");
            return;
        }
    } else {
        if (!formData.username || !formData.password) {
            setError("Informe usuário/email e senha.");
            return;
        }
    }

    // Tratamento do ID para uso no sistema (sanitização básica)
    // No futuro, isso seria substituído por uma chamada real à API de Auth
    const safeId = formData.username.trim().toLowerCase().replace(/[^a-z0-9]/g, '_');

    // Simula delay de rede
    setTimeout(() => {
        onLogin(safeId);
    }, 500);
  };

  const toggleMode = () => {
    setIsRegistering(!isRegistering);
    setError(null);
    setFormData({ name: '', username: '', email: '', password: '', confirmPassword: '' });
