                        </div>

                        <div className="group">
                            <label className="block text-amber-900 text-[10px] uppercase tracking-widest mb-2">Cosmologia</label>
                            <input
                                type="text"
                                value={formData.cosmology}
                                onChange={e => setFormData({ ...formData, cosmology: e.target.value })}
