                    ))}
                </div>
            </div>

            {/* COLUNA 2: PERSONAGENS */}
            <div className="flex-1 flex flex-col h-[400px] md:h-full md:border-l md:border-stone-900 md:pl-8">
                <h3 className="text-amber-900 text-[10px] uppercase tracking-widest border-b border-stone-900 pb-2 mb-4 shrink-0">Galeria de Atores</h3>
                <div className="space-y-3 flex-1 overflow-y-auto custom-scrollbar md:pr-2 min-h-0">
                    {characters.length === 0 && (
                            <div className="p-4 text-stone-700 text-xs italic border border-dashed border-stone-900">
                            Vazio.
                            </div>
                    )}
                    {characters.map(c => (
                        <button
                            key={c.id}
                            onClick={() => setSelectedCharacter(c.id)}
                            className={`w-full text-left p-4 rounded-sm border transition-all ${
                                selectedCharacter === c.id 
                                ? 'bg-amber-900/20 border-amber-700' 
                                : 'bg-stone-900/30 border-stone-800 hover:bg-stone-900'
                            }`}
                        >
                            <div className="flex justify-between mb-1">
                                <span className={`font-serif text-base ${selectedCharacter === c.id ? 'text-amber-500' : 'text-stone-300'}`}>
                                    {c.name}
                                </span>
                            </div>
                            <span className="text-[9px] uppercase tracking-wider text-stone-500 border border-stone-800 px-2 rounded-full">
                                {c.archetype}
                            </span>
                        </button>
                    ))}
                </div>
            </div>

        </div>
      </div>
    </div>
  );
};

export default AdventureLauncher;

import React from 'react';
import GameHeader from '../GameHeader';
import WorldStatePanel from '../WorldStatePanel';
import BottomNav, { NavTab } from '../BottomNav';
import { GameState } from '../../types';

interface GameLayoutProps {
  children: React.ReactNode;
  gameState: GameState | null;
  currentView: string;
  isSidebarOpen: boolean;
  activeTab: NavTab;
  onToggleSidebar: () => void;
  onReset: () => void;
  onSave: () => void;
  onLoad: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onTabChange: (tab: NavTab) => void;
}

const GameLayout: React.FC<GameLayoutProps> = ({
  children,
  gameState,
  currentView,
  isSidebarOpen,
  activeTab,
  onToggleSidebar,
  onReset,
  onSave,
  onLoad,
  onTabChange
}) => {
  const isGameActive = currentView === 'GAME';

  return (
    <div className="flex h-screen bg-stone-950 text-stone-200 overflow-hidden relative">

      {/* Main Content */}
      {/* FIX: Adicionado 'pb-safe' e margem inferior condicional para reservar espaço para a BottomNav */}
      <div className={`flex-1 flex flex-col min-w-0 relative transition-all duration-300 
        ${isSidebarOpen && isGameActive ? 'mr-0 md:mr-80' : 'mr-0'} 
        ${!isGameActive ? 'mb-16 md:mb-20' : ''}
      `}>

        <GameHeader 
          gameState={gameState}
          setupMode={!isGameActive}
          isSidebarOpen={isSidebarOpen}
          onToggleSidebar={onToggleSidebar}
          onReset={onReset}
          onSave={onSave}
          onLoad={onLoad}
        />

        {children}
      </div>

      {/* Sidebar - Only active in GAME view */}
      {isGameActive && (
        <WorldStatePanel 
          gameState={gameState} 
          isOpen={isSidebarOpen} 
          onToggle={onToggleSidebar} 
        />
      )}

      {/* Bottom Navigation - Only active when NOT in game */}
      {!isGameActive && (
        <BottomNav activeTab={activeTab} onTabChange={onTabChange} />
      )}

    </div>
  );
};

export default GameLayout;

