                    <button
                        onClick={handleSave}
                        className="px-6 py-4 bg-amber-900/20 border border-amber-900/30 text-amber-500 hover:bg-amber-900/40 hover:border-amber-700 transition-colors text-xs uppercase tracking-widest w-full text-center"
