// --- EXISTING RAG FUNCTIONS ---

/**
 * Envia o Snapshot completo do turno para o Backend.
 */
export const ingestUnifiedMemory = async (payload: UnifiedIngestPayload) => {
  try {
    const response = await fetch(`${SERVER_URL}/ingest/unified`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
        console.warn("Triple Store Ingest Error:", response.statusText);
    }
  } catch (error) {
    console.debug("Backend offline (Ingest skipped).");
  }
};

/**
 * Busca memórias semânticas (Vector Search) baseadas em similaridade de texto.
 */
export const retrieveContext = async (query: string, universeId: string, userId: string): Promise<string[]> => {
  try {
    const response = await fetch(`${SERVER_URL}/query/vector`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
          query: query,
          universeId: universeId,
          userId: userId
      })
    });

    if (!response.ok) return [];

    const data = await response.json();
    return data.documents || [];
  } catch (error) {
    return [];
  }
};

/**
 * NOVO: Busca relacionamentos diretos no Grafo (Neo4j).
 * Essencial para o modo de Investigação saber "quem conhece quem" ou "o que está neste local".
 */
export const retrieveGraphContext = async (entityName: string, universeId: string, userId: string): Promise<GraphEdge[]> => {
  try {
    const response = await fetch(`${SERVER_URL}/query/graph`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
          entity: entityName,
          universeId: universeId,
          userId: userId,
          depth: 1 // Busca apenas conexões diretas para economizar tokens
      })
    });

    if (!response.ok) return [];
    const data = await response.json();
    return data.edges || [];
  } catch (error) {
    console.warn("Graph retrieval failed:", error);
    return [];
  }
};

/**
 * Verifica se o servidor backend está online.
 */
export const checkBackendHealth = async (): Promise<boolean> => {
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 2000);

    const response = await fetch(`${SERVER_URL}/health`, { // Endpoint padrão de health check
      method: 'GET',
      headers: { 'Content-Type': 'application/json' },
      signal: controller.signal
    });

    clearTimeout(timeoutId);
    return response.ok;
  } catch (error) {
    return false;
  }
};

import React, { useState } from 'react';
import { loginUser, registerUser } from '../../services/ragService';

interface LoginScreenProps {
  onLogin: (userId: string) => void;
}

const LoginScreen: React.FC<LoginScreenProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    username: '',
    email: '',
    password: '',
    confirmPassword: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    setError(null); // Limpa erro ao digitar
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    // Validação Básica Frontend
    if (isRegistering) {
        if (!formData.firstName || !formData.lastName || !formData.username || !formData.email || !formData.password) {
            setError("Todos os campos são obrigatórios.");
            setLoading(false);
            return;
        }
        if (formData.password !== formData.confirmPassword) {
            setError("As senhas não coincidem.");
            setLoading(false);
            return;
        }
    } else {
        if (!formData.username || !formData.password) {
            setError("Informe usuário/email e senha.");
            setLoading(false);
            return;
        }
    }

    try {
        let result;
        if (isRegistering) {
            // CALL BACKEND REGISTER
            result = await registerUser({
                username: formData.username,
                email: formData.email,
                password: formData.password,
                first_name: formData.firstName,
                last_name: formData.lastName
            });
        } else {
            // CALL BACKEND LOGIN
            result = await loginUser({
                username: formData.username,
                password: formData.password
            });
        }

        // Se sucesso, o backend deve retornar o userId ou token
        if (result && result.userId) {
            onLogin(result.userId);
        } else {
            setError("Erro desconhecido na resposta do servidor.");
        }

    } catch (err: any) {
        console.error(err);
        setError(err.message || "Falha na conexão com o servidor.");
    } finally {
        setLoading(false);
    }
  };

  const toggleMode = () => {
    setIsRegistering(!isRegistering);
    setError(null);
    setFormData({ firstName: '', lastName: '', username: '', email: '', password: '', confirmPassword: '' });
  };

  return (
    <div className="fixed inset-0 z-50 bg-stone-950 flex flex-col items-center justify-center font-sans overflow-y-auto py-10 px-4">
        {/* Animated Background Mesh */}
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(66,32,6,0.15)_0%,_rgba(12,10,9,1)_70%)] pointer-events-none"></div>
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-amber-900/50 to-transparent"></div>

        {/* 
            CONTAINER RESPONSIVO:
            Mobile: max-w-md (estreito)
            Desktop (md+): max-w-4xl (largo)
        */}
        <div className="relative z-10 w-full max-w-md md:max-w-4xl p-8 md:p-12 animate-fade-in bg-stone-900/20 backdrop-blur-sm border border-stone-800 rounded-sm shadow-2xl">

            {/* 
                GRID RESPONSIVO:
                Mobile: flex-col (um em cima do outro)
                Desktop: flex-row (lado a lado)
            */}
            <div className="flex flex-col md:flex-row gap-8 md:gap-12">

                {/* --- LADO ESQUERDO: BRANDING (No topo no mobile) --- */}
                <div className="flex flex-col justify-center text-center md:text-left md:w-5/12 space-y-4">
                    <div>
                        <h1 className="text-4xl md:text-6xl font-serif text-stone-200 tracking-[0.2em] uppercase leading-none">
                            Cronos
                        </h1>
                        <div className="h-px w-16 bg-amber-900/50 mx-auto md:mx-0 mt-4 mb-2"></div>
                        <p className="text-stone-500 text-xs md:text-sm uppercase tracking-widest">
                            O Mundo Vivo
                        </p>
                    </div>

                    <div className="hidden md:block text-stone-600 text-xs italic leading-relaxed pt-4 border-t border-stone-800/50">
                        "A realidade é apenas uma memória compartilhada. Crie sua identidade e deixe sua marca na eternidade."
                    </div>

                    <div className="hidden md:block">
                        <div className="flex gap-2 justify-center md:justify-start mt-4">
                            <div className="w-2 h-2 bg-stone-800 rounded-full animate-pulse"></div>
                            <div className="w-2 h-2 bg-stone-800 rounded-full animate-pulse delay-100"></div>
                            <div className="w-2 h-2 bg-amber-900 rounded-full animate-pulse delay-200"></div>
                        </div>
                    </div>
                </div>

                {/* --- LADO DIREITO: FORMULÁRIO --- */}
                {/* Adicionamos uma borda esquerda apenas no Desktop */}
                <div className="md:w-7/12 md:border-l md:border-stone-800 md:pl-12 flex flex-col justify-center">

                    <div className="mb-6 text-center md:text-left">
