// Helper para tratar erros da API de forma padronizada
const handleApiError = async (response: Response) => {
  const text = await response.text();
  try {
      const json = JSON.parse(text);
      if (json.detail) {
           return new Error(json.detail);
      }
  } catch (e) {
      // Se falhar o parse do JSON, usa o texto puro ou status
  }
  return new Error(text || `Erro ${response.status}: ${response.statusText}`);
};

