        { name: "Ilha de Ferro", description: "Fortaleza humana." },
    ],
    chronicles: [],
    createdAt: 1715420000000
  }
];

const DEFAULT_CHARACTERS: CharacterTemplate[] = [
  {
    id: 'char-kael',
    userId: 'system',
    name: 'Kael',
    description: 'Um ator focado em papéis de sobrevivência.',
    archetype: 'O Sobrevivente',
    adventuresPlayed: 1,
    createdAt: 1715420000000
  }
];

// O hook agora aceita userId
export const useLibrary = (userId?: string) => {
  const [universes, setUniverses] = useState<UniverseTemplate[]>([]);
  const [characters, setCharacters] = useState<CharacterTemplate[]>([]);
  const [adventures, setAdventures] = useState<AdventureRecord[]>([]);

  // Prefix keys with userId to isolate data
  const getKey = (base: string) => userId ? `${base}_${userId}` : null;

  // Load when userId changes (Hybrid Strategy: Local + Server)
  useEffect(() => {
    if (!userId) {
        setUniverses([]);
        setCharacters([]);
        setAdventures([]);
        return;
    }

    const uKey = getKey('cronos_universes');
    const cKey = getKey('cronos_characters');
    const aKey = getKey('cronos_adventures');

    const loadLocal = () => {
        if (uKey && cKey && aKey) {
            const savedUniverses = localStorage.getItem(uKey);
            const savedCharacters = localStorage.getItem(cKey);
            const savedAdventures = localStorage.getItem(aKey);

            if (savedUniverses) setUniverses(JSON.parse(savedUniverses));
            else setUniverses(DEFAULT_UNIVERSES);

            if (savedCharacters) setCharacters(JSON.parse(savedCharacters));
            else setCharacters(DEFAULT_CHARACTERS);

            if (savedAdventures) setAdventures(JSON.parse(savedAdventures));
            else setAdventures([]);
        }
    };

    // 1. Load Local first (Instant UI)
    loadLocal();

    // 2. Try Fetch from Server (Persistence)
    fetchUserLibrary(userId).then(remoteLib => {
        if (remoteLib) {
            // Merge logic could be complex, for now, if server has data, we trust server over local for list completeness
            // Or we just append. For simplicity, let's trust server if it returns non-empty arrays
            if (remoteLib.universes?.length > 0) {
                setUniverses(remoteLib.universes);
                if(uKey) localStorage.setItem(uKey, JSON.stringify(remoteLib.universes));
            }
            if (remoteLib.characters?.length > 0) {
                setCharacters(remoteLib.characters);
                if(cKey) localStorage.setItem(cKey, JSON.stringify(remoteLib.characters));
            }
            if (remoteLib.adventures?.length > 0) {
                setAdventures(remoteLib.adventures);
                if(aKey) localStorage.setItem(aKey, JSON.stringify(remoteLib.adventures));
            }
        }
    });

  }, [userId]);

  // Helpers de save internos
  const saveU = (list: UniverseTemplate[]) => {
      const key = getKey('cronos_universes');
      if (key) {
          localStorage.setItem(key, JSON.stringify(list));
          setUniverses(list);
      }
  };
  const saveC = (list: CharacterTemplate[]) => {
      const key = getKey('cronos_characters');
      if (key) {
          localStorage.setItem(key, JSON.stringify(list));
          setCharacters(list);
      }
  };
  const saveA = (list: AdventureRecord[]) => {
      const key = getKey('cronos_adventures');
      if (key) {
          localStorage.setItem(key, JSON.stringify(list));
          setAdventures(list);
      }
  };

  // Actions
  const addUniverse = (template: Omit<UniverseTemplate, 'id' | 'createdAt' | 'userId'>) => {
    if (!userId) return;
    const newUni: UniverseTemplate = { ...template, id: crypto.randomUUID(), userId, createdAt: Date.now() };
    saveU([...universes, newUni]);
    syncUniverse(userId, newUni);
  };

  const evolveUniverse = (universeId: string, updates: any) => {
    let targetUniverse: UniverseTemplate | null = null;
    const updatedList = universes.map(u => {
      if (u.id !== universeId) return u;

      const newTimeline = updates.newEvents ? updates.newEvents.map((e:string) => ({ year: 'Presente', event: e, era: 'Era do Jogador' })) : [];
      let updatedWorlds = u.worlds || [];
      if (updates.newWorld && !updatedWorlds.some((w:any) => w.name === updates.newWorld.name)) {
          updatedWorlds = [...updatedWorlds, updates.newWorld];
      }
      const updated = {
        ...u,
        knownTruths: [...(u.knownTruths || []), ...(updates.newTruths || [])], 
        chronicles: [...(u.chronicles || []), ...newTimeline], 
        worlds: updatedWorlds
      };
      targetUniverse = updated;
      return updated;
    });
    saveU(updatedList);
    // Sync to Backend
    if (userId && targetUniverse) syncUniverse(userId, targetUniverse);
  };

  const trackCharacterUsage = (characterId: string) => {
      const updatedList = characters.map(c => c.id === characterId ? { ...c, adventuresPlayed: (c.adventuresPlayed || 0) + 1 } : c);
      saveC(updatedList);
      // Sync update
      const updatedChar = updatedList.find(c => c.id === characterId);
      if (userId && updatedChar) syncCharacter(userId, updatedChar);
  };

  const addAdventureRecord = (u: UniverseTemplate, c: CharacterTemplate) => {
      if (!userId) return;
      const newRecord: AdventureRecord = {
          id: crypto.randomUUID(),
          userId,
          universeId: u.id,
          characterId: c.id,
          name: `${c.name} em ${u.name}`,

          // Legacy fields mapping
          characterName: c.name,
          universeName: u.name,
          universeGenre: u.genre,
          startDate: Date.now(),
          lastLocation: 'Início',
          createdAt: Date.now()
      };
      saveA([newRecord, ...adventures]);
      // Sync metadata
      syncAdventureMetadata(userId, newRecord);
  };

  const deleteAdventureRecord = (id: string) => saveA(adventures.filter(a => a.id !== id));
  const deleteUniverse = (id: string) => saveU(universes.filter(u => u.id !== id));

  const addCharacter = (template: Omit<CharacterTemplate, 'id' | 'createdAt' | 'userId'>) => {
    if (!userId) return;
    const newChar: CharacterTemplate = { ...template, id: crypto.randomUUID(), userId, createdAt: Date.now() };
    saveC([...characters, newChar]);
    syncCharacter(userId, newChar);
  };
  const deleteCharacter = (id: string) => saveC(characters.filter(c => c.id !== id));

  const restoreDefaults = () => {
    saveU(DEFAULT_UNIVERSES);
    saveC(DEFAULT_CHARACTERS);
    saveA([]);
  };

  return {
    universes,
    characters,
    adventures,
    addUniverse,
    evolveUniverse,
    trackCharacterUsage,
    addAdventureRecord,
    deleteAdventureRecord,
    deleteUniverse,
    addCharacter,
    deleteCharacter,
    restoreDefaults
  };
};

import { UniverseTemplate, CharacterTemplate, AdventureRecord } from "../../types";
import { apiClient } from "./core";

// --- Helpers de Sanitização (DTOs) ---
// Garante que o objeto enviado ao backend tenha TODOS os campos esperados,
// convertendo undefined para defaults seguros ([], "", null) e datas para ISO String.

const sanitizeUniverse = (u: UniverseTemplate) => ({
    id: u.id,
    userId: u.userId,
    name: u.name,
    description: u.description || "",
    genre: u.genre,
    image: u.image || null,

    // Arrays: Garante [] ao invés de undefined
    physics: u.physics || [],
    knownTruths: u.knownTruths || [],
    chronicles: u.chronicles || [],
    champions: u.champions || [],
    worlds: u.worlds || [],

    // Enums e Strings Opcionais
    structure: u.structure || 'singular_world',
    navigationMethod: u.navigationMethod || 'physical',
    magicSystem: u.magicSystem || "",
    cosmology: u.cosmology || "",

    // Data: Garante ISO String (Python prefere ISO a Timestamp numérico)
    createdAt: new Date(u.createdAt || Date.now()).toISOString()
});

const sanitizeCharacter = (c: CharacterTemplate) => ({
    id: c.id,
    userId: c.userId,
    name: c.name,
    description: c.description || "",
    archetype: c.archetype,
    image: c.image || null,
    stats: c.stats || {},
    adventuresPlayed: c.adventuresPlayed || 0,
    createdAt: new Date(c.createdAt || Date.now()).toISOString()
});

const sanitizeAdventure = (a: AdventureRecord) => ({
    id: a.id,
    userId: a.userId,
    universeId: a.universeId,
    characterId: a.characterId,
    name: a.name,
    description: a.description || "",
    currentStep: a.currentStep || "",

    // Legacy fields (Garante string vazia se faltar)
    characterName: a.characterName || "",
    universeName: a.universeName || "",
    universeGenre: a.universeGenre || "",
    lastLocation: a.lastLocation || "",

    startDate: new Date(a.startDate || Date.now()).toISOString(),
    createdAt: new Date(a.createdAt || Date.now()).toISOString()
});

// --- Endpoints ---

export const fetchUserLibrary = async (userId: string) => {
  try {
    return await apiClient.get<any>(`/library/${userId}`);
  } catch (error) {
    console.warn("Offline: Não foi possível baixar a biblioteca do servidor.");
    return null;
  }
};

export const syncUniverse = async (userId: string, universe: UniverseTemplate) => {
  try {
    const payload = sanitizeUniverse({ ...universe, userId });
    await apiClient.post('/library/universe', payload);
  } catch (e) { 
    console.warn("Sync Universe failed", e); 
  }
};

export const syncCharacter = async (userId: string, character: CharacterTemplate) => {
  try {
    const payload = sanitizeCharacter({ ...character, userId });
    await apiClient.post('/library/character', payload);
  } catch (e) { 
    console.warn("Sync Character failed", e); 
  }
};

export const syncAdventureMetadata = async (userId: string, adventure: AdventureRecord) => {
  try {
    const payload = sanitizeAdventure({ ...adventure, userId });
    await apiClient.post('/library/adventure', payload);
  } catch (e) { 
    console.warn("Sync Adventure failed", e); 
  }
};

const DEFAULT_URL = "http://localhost:8000";
const STORAGE_KEY = "cronos_api_url";

// --- Gerenciamento de URL ---

export const getServerUrl = (): string => {
  if (typeof localStorage === 'undefined') return DEFAULT_URL;
  let url = localStorage.getItem(STORAGE_KEY) || DEFAULT_URL;
  return url.replace(/\/$/, "");
};

export const setServerUrl = (url: string) => {
  const cleanUrl = url.trim().replace(/\/$/, "");
  localStorage.setItem(STORAGE_KEY, cleanUrl);
};

// --- Cliente HTTP Base ---

const getHeaders = () => ({
  'Content-Type': 'application/json',
  'ngrok-skip-browser-warning': 'true'
});

export class ApiError extends Error {
  status: number;
  constructor(message: string, status: number) {
    super(message);
    this.status = status;
    this.name = 'ApiError';
  }
}

const handleApiError = async (response: Response) => {
  if (response.status === 503) {
      throw new ApiError("Erro 503: Túnel Ngrok ativo, mas o Backend Python está offline.", 503);
  }

  const contentType = response.headers.get("content-type");
  if (contentType && contentType.indexOf("application/json") === -1) {
       throw new ApiError(`Erro de Conexão (${response.status}): Verifique a URL do Ngrok.`, response.status);
  }

  const text = await response.text();
  try {
      const json = JSON.parse(text);
      if (json.detail) {
           // FastAPI Validation Error (Array or String)
           // Extrai detalhes úteis do 422 (ex: qual campo está faltando)
           const msg = Array.isArray(json.detail) 
             ? json.detail.map((e: any) => `${e.loc?.join('.') || 'Campo'}: ${e.msg}`).join('\n')
             : json.detail;
           throw new ApiError(msg, response.status);
      }
  } catch (e) {
      if (e instanceof ApiError) throw e;
      // Falha ao parsear JSON, continua para erro genérico
  }
  throw new ApiError(text || `Erro ${response.status}: ${response.statusText}`, response.status);
};

const handleNetworkError = (error: any, url: string) => {
    if (error.message && error.message.includes('Failed to fetch')) {
        // Enriched error message
        throw new Error(`Falha na conexão com ${url}. O servidor está offline ou a URL está incorreta.`);
    }
    throw error;
};

export const apiClient = {
  get: async <T>(endpoint: string): Promise<T> => {
    const url = `${getServerUrl()}${endpoint}`;
    try {
      const response = await fetch(url, {
        method: 'GET',
        headers: getHeaders()
      });
      if (!response.ok) await handleApiError(response);
      return await response.json() as T;
    } catch (error: any) {
      handleNetworkError(error, url);
      throw error; // Fallback
    }
  },

  post: async <T>(endpoint: string, body: any): Promise<T> => {
    const url = `${getServerUrl()}${endpoint}`;
    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: getHeaders(),
        body: JSON.stringify(body)
      });
      if (!response.ok) await handleApiError(response);
      // Alguns endpoints podem não retornar corpo (204 No Content)
      if (response.status === 204) return {} as T;
      return await response.json() as T;
    } catch (error: any) {
      handleNetworkError(error, url);
      throw error; // Fallback
    }
  },

  // Health Check rápido com timeout customizado
  checkHealth: async (): Promise<boolean> => {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 2000);

      const response = await fetch(`${getServerUrl()}/health`, {
        method: 'GET',
        headers: getHeaders(),
        signal: controller.signal
      });

      clearTimeout(timeoutId);
      return response.ok;
    } catch (error) {
      return false;
    }
  }
};

import React, { useState, useEffect } from 'react';
import { useGameEngine } from './useGameEngine';
import { usePersistence } from './usePersistence';
import { useLibrary } from './useLibrary';
import { checkBackendHealth } from '../services/ragService';
import { NavTab } from '../components/BottomNav';
import { UniverseTemplate, CharacterTemplate } from '../types';

export type ViewState = 'ADVENTURE_LAUNCHER' | 'ADVENTURE_LIST' | 'UNIVERSE_LIST' | 'UNIVERSE_CREATOR' | 'CHARACTER_LIST' | 'CHARACTER_CREATOR' | 'SETTINGS' | 'GAME';

export const useAppController = () => {
  // Auth State
  const [userId, setUserId] = useState<string | null>(null);

  const [hasApiKey, setHasApiKey] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isInvestigationMode, setIsInvestigationMode] = useState(false);
  const [currentView, setCurrentView] = useState<ViewState>('ADVENTURE_LAUNCHER');
  const [backendStatus, setBackendStatus] = useState<'checking' | 'online' | 'offline'>('checking');

  // Check for stored session on mount
  useEffect(() => {
    const storedUser = localStorage.getItem('cronos_session_user');
    if (storedUser) setUserId(storedUser);
  }, []);

  // Library & Persistence (Depende do userId)
  const { universes, characters, addUniverse, addCharacter, restoreDefaults, evolveUniverse, trackCharacterUsage, addAdventureRecord } = useLibrary(userId || undefined);
  const { saveGame, parseSaveFile } = usePersistence();

  // Game Engine
  const { gameState, isProcessing, startGame, performAction, resetGame, restoreGame } = useGameEngine(evolveUniverse);

  // --- Effects ---

  // Auto-open sidebar on game start
  useEffect(() => {
    if (gameState && currentView === 'GAME') {
      setIsSidebarOpen(true);
    }
  }, [gameState, currentView]);

  // Check Backend Health when entering Settings
  useEffect(() => {
    if (currentView === 'SETTINGS') {
      setBackendStatus('checking');
      checkBackendHealth().then(isOnline => {
        setBackendStatus(isOnline ? 'online' : 'offline');
      });
    }
  }, [currentView]);

  // --- Auth Handlers ---
  const handleLogin = (id: string) => {
      localStorage.setItem('cronos_session_user', id);
      setUserId(id);
      setCurrentView('ADVENTURE_LAUNCHER');
  };

  const handleLogout = () => {
      // Removemos o window.confirm daqui para tratar na UI (UX melhor)
      localStorage.removeItem('cronos_session_user');

      // Reset total do estado do jogo
      resetGame();
      setIsSidebarOpen(false);

      // Mudança de view e usuário
      setCurrentView('ADVENTURE_LAUNCHER');
      setUserId(null);
  };

  // --- Handlers ---

  const handleStartAdventure = (u: UniverseTemplate, c: CharacterTemplate) => {
    if (!userId) return;

    trackCharacterUsage(c.id);
    addAdventureRecord(u, c);

    const physicsBlock = u.physics && u.physics.length > 0 ? `LEIS DA REALIDADE (Imutáveis):\n${u.physics.map(p=>`- ${p}`).join('\n')}` : '';
    const truthsBlock = u.knownTruths && u.knownTruths.length > 0 ? `VERDADES DESCOBERTAS (Conhecimento Acumulado):\n${u.knownTruths.map(t=>`- ${t}`).join('\n')}` : '';
    const timelineBlock = u.chronicles && u.chronicles.length > 0 ? `CRONOLOGIA CANÔNICA DO UNIVERSO (HISTÓRICO COMPARTILHADO):\n${u.chronicles.map(t=>`[${t.year}] ${t.event}`).join('\n')}` : '';
    const legendsBlock = u.champions && u.champions.length > 0 ? `LENDAS E HERÓIS PASSADOS:\n${u.champions.map(ch => `- ${ch.characterName}: ${ch.feat} (${ch.status})`).join('\n')}` : '';
    const magicBlock = u.magicSystem ? `SISTEMA DE MAGIA/TECNOLOGIA: ${u.magicSystem}` : '';

    const structureLabel = u.structure === 'star_cluster' ? "AGLOMERADO ESTELAR (Viagem entre Planetas)" : u.structure === 'singular_world' ? "PLANETA ÚNICO/INFINITO (Viagem Regional)" : "NEXUS MULTIVERSAL";
    const navLabel = u.navigationMethod === 'interstellar_ship' ? "NAVES ESPACIAIS" : u.navigationMethod === 'magical_gate' ? "PORTAIS MÁGICOS" : "FÍSICA (Caminhada/Veículos)";

    const settingInstruction = `
    DECISÃO DO MESTRE DE JOGO NECESSÁRIA:
    O jogador não especificou um local de início.
    Com base no Arquétipo do personagem (${c.archetype}) e no Gênero do Universo (${u.genre}), escolha um local inicial dramático e apropriado.
    `;

    const fullSettingContext = `
      UNIVERSE CONTAINER: ${u.name} (${u.genre})
      ESTRUTURA FÍSICA: ${structureLabel}
      MÉTODO DE VIAGEM PREDOMINANTE: ${navLabel}
      DESCRIÇÃO DO UNIVERSO: ${u.description}
      COSMOLOGIA: ${u.cosmology || 'Desconhecida'}
      ${physicsBlock}
      ${magicBlock}
      ${truthsBlock}
      ${timelineBlock}
      ${legendsBlock}
      ---
      STARTING INSTRUCTION: ${settingInstruction}
      ---
    `;

    // Pass userId to startGame
    startGame(c, fullSettingContext, u.id, u.name, userId);
    setCurrentView('GAME');
  };

  const handleLoadGame = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const loadedState = await parseSaveFile(file);
      restoreGame(loadedState);
      setCurrentView('GAME');
    } catch (err) {
      console.error(err);
      alert("Arquivo de save inválido ou corrompido.");
    }
  };

  const handleExitToHub = () => {
    resetGame();
    setCurrentView('ADVENTURE_LAUNCHER');
  };

  const getActiveTab = (): NavTab => {
    if (currentView === 'ADVENTURE_LIST') return 'ADVENTURES';
    if (currentView === 'UNIVERSE_LIST' || currentView === 'UNIVERSE_CREATOR') return 'UNIVERSES';
    if (currentView === 'CHARACTER_LIST' || currentView === 'CHARACTER_CREATOR') return 'CHARACTERS';
    if (currentView === 'SETTINGS') return 'SETTINGS';
    return 'PLAY';
  };

  const handleTabChange = (tab: NavTab) => {
    switch (tab) {
      case 'PLAY': setCurrentView('ADVENTURE_LAUNCHER'); break;
      case 'ADVENTURES': setCurrentView('ADVENTURE_LIST'); break;
      case 'UNIVERSES': setCurrentView('UNIVERSE_LIST'); break;
      case 'CHARACTERS': setCurrentView('CHARACTER_LIST'); break;
      case 'SETTINGS': setCurrentView('SETTINGS'); break;
    }
  };

  return {
    state: {
      userId,
      hasApiKey,
      isSidebarOpen,
      isInvestigationMode,
      currentView,
      backendStatus,
      gameState,
      isProcessing,
      universes,
      characters
    },
    actions: {
      setHasApiKey,
      setIsSidebarOpen,
      setIsInvestigationMode,
      setCurrentView,
      addUniverse,
      addCharacter,
      restoreDefaults,
      performAction,
      saveGame,
      handleStartAdventure,
      handleLoadGame,
      handleExitToHub,
      handleTabChange,
      handleLogin,
      handleLogout
    },
    computed: {
      activeTab: getActiveTab()
    }
  };
};

