// O hook agora aceita userId
export const useLibrary = (userId?: string) => {
  const [universes, setUniverses] = useState<UniverseTemplate[]>([]);
  const [characters, setCharacters] = useState<CharacterTemplate[]>([]);
  const [adventures, setAdventures] = useState<AdventureRecord[]>([]);

  // Prefix keys with userId to isolate data
  const getKey = (base: string) => userId ? `${base}_${userId}` : null;

  // Load when userId changes (Hybrid Strategy: Local + Server)
  useEffect(() => {
    if (!userId) {
        setUniverses([]);
        setCharacters([]);
        setAdventures([]);
        return;
    }

    const uKey = getKey('cronos_universes');
    const cKey = getKey('cronos_characters');
    const aKey = getKey('cronos_adventures');

    const loadLocal = () => {
        if (uKey && cKey && aKey) {
            const savedUniverses = localStorage.getItem(uKey);
            const savedCharacters = localStorage.getItem(cKey);
            const savedAdventures = localStorage.getItem(aKey);

            if (savedUniverses) setUniverses(JSON.parse(savedUniverses));
            else setUniverses(DEFAULT_UNIVERSES);

            if (savedCharacters) setCharacters(JSON.parse(savedCharacters));
            else setCharacters(DEFAULT_CHARACTERS);

            if (savedAdventures) setAdventures(JSON.parse(savedAdventures));
            else setAdventures([]);
        }
    };

    // 1. Load Local first (Instant UI)
    loadLocal();

    // 2. Try Fetch from Server (Persistence)
    // Only update if server has data to prevent overwriting local work with empty server state on new accounts
    fetchUserLibrary(userId).then(remoteLib => {
        if (remoteLib) {
            if (remoteLib.universes?.length > 0) {
                setUniverses(remoteLib.universes);
                if(uKey) localStorage.setItem(uKey, JSON.stringify(remoteLib.universes));
            }
            if (remoteLib.characters?.length > 0) {
                setCharacters(remoteLib.characters);
                if(cKey) localStorage.setItem(cKey, JSON.stringify(remoteLib.characters));
            }
            if (remoteLib.adventures?.length > 0) {
                setAdventures(remoteLib.adventures);
                if(aKey) localStorage.setItem(aKey, JSON.stringify(remoteLib.adventures));
            }
        }
    });

  }, [userId]);

  // Helpers de save internos
  const saveU = (list: UniverseTemplate[]) => {
      const key = getKey('cronos_universes');
      if (key) {
          localStorage.setItem(key, JSON.stringify(list));
          setUniverses(list);
      }
  };
  const saveC = (list: CharacterTemplate[]) => {
      const key = getKey('cronos_characters');
      if (key) {
          localStorage.setItem(key, JSON.stringify(list));
          setCharacters(list);
      }
  };
  const saveA = (list: AdventureRecord[]) => {
      const key = getKey('cronos_adventures');
      if (key) {
          localStorage.setItem(key, JSON.stringify(list));
          setAdventures(list);
      }
  };

  // Actions
  const addUniverse = (template: Omit<UniverseTemplate, 'id' | 'createdAt' | 'userId'>) => {
    if (!userId) return;
    const newUni: UniverseTemplate = { ...template, id: crypto.randomUUID(), userId, createdAt: Date.now() };
    saveU([...universes, newUni]);
    syncUniverse(userId, newUni);
  };

  const evolveUniverse = (universeId: string, updates: any) => {
    let targetUniverse: UniverseTemplate | null = null;
    const updatedList = universes.map(u => {
      if (u.id !== universeId) return u;

      const newTimeline = updates.newEvents ? updates.newEvents.map((e:string) => ({ year: 'Presente', event: e, era: 'Era do Jogador' })) : [];
      let updatedWorlds = u.worlds || [];
      if (updates.newWorld && !updatedWorlds.some((w:any) => w.name === updates.newWorld.name)) {
          updatedWorlds = [...updatedWorlds, updates.newWorld];
      }
      const updated = {
        ...u,
        knownTruths: [...(u.knownTruths || []), ...(updates.newTruths || [])], 
        chronicles: [...(u.chronicles || []), ...newTimeline], 
        worlds: updatedWorlds
      };
      targetUniverse = updated;
      return updated;
    });
    saveU(updatedList);
    // Sync to Backend
    if (userId && targetUniverse) syncUniverse(userId, targetUniverse);
  };

  const trackCharacterUsage = (characterId: string) => {
      const updatedList = characters.map(c => c.id === characterId ? { ...c, adventuresPlayed: (c.adventuresPlayed || 0) + 1 } : c);
      saveC(updatedList);
      // Sync update
      const updatedChar = updatedList.find(c => c.id === characterId);
      if (userId && updatedChar) syncCharacter(userId, updatedChar);
  };

  const addAdventureRecord = (u: UniverseTemplate, c: CharacterTemplate): string => {
      if (!userId) return "";
      const id = crypto.randomUUID();
      const newRecord: AdventureRecord = {
          id: id,
          userId,
          universeId: u.id,
          characterId: c.id,
          name: `${c.name} em ${u.name}`,

          // Legacy fields mapping
          characterName: c.name,
          universeName: u.name,
          universeGenre: u.genre,
          startDate: Date.now(),
          lastLocation: 'Início',
          createdAt: Date.now()
      };
      saveA([newRecord, ...adventures]);
      // Sync metadata
      syncAdventureMetadata(userId, newRecord);
      return id;
  };

  const deleteAdventureRecord = (id: string) => saveA(adventures.filter(a => a.id !== id));
  const deleteUniverse = (id: string) => saveU(universes.filter(u => u.id !== id));

  const addCharacter = (template: Omit<CharacterTemplate, 'id' | 'createdAt' | 'userId'>) => {
    if (!userId) {
        console.error("Tentativa de adicionar personagem sem usuário logado.");
        return;
    }

    const newChar: CharacterTemplate = { 
        ...template,
        id: crypto.randomUUID(), 
        userId, 
        createdAt: Date.now(),
        // Defaults seguros
        stats: template.stats || {},
        adventuresPlayed: template.adventuresPlayed || 0
    };

    saveC([...characters, newChar]);
    syncCharacter(userId, newChar);
  };

  const deleteCharacter = (id: string) => saveC(characters.filter(c => c.id !== id));

  const restoreDefaults = () => {
    saveU(DEFAULT_UNIVERSES);
    saveC(DEFAULT_CHARACTERS);
    saveA([]);
  };

  return {
    universes,
    characters,
    adventures,
    addUniverse,
    evolveUniverse,
    trackCharacterUsage,
    addAdventureRecord,
    deleteAdventureRecord,
    deleteUniverse,
    addCharacter,
    deleteCharacter,
    restoreDefaults
  };
};

import { GraphEdge } from "../../types";
import { apiClient } from "./core";

// Payload unificado para envio aos 3 bancos de dados
export interface UnifiedIngestPayload {
  userId: string;
  universeId: string;
  turnId: number;
  timestamp: string; 

  // Chroma DB
  vectorData: {
    text: string;
    type: 'turn' | 'lore' | 'intro';
    location: string;
  };

  // SQLite Logs
  sqlData: {
    playerStatus: any;
    inventory: string[];
    worldState: any;
  };

  // Neo4j Graph (Frontend usa source/target, Backend espera subject/object)
  graphData: GraphEdge[];
}

/**
 * Envia o "Snapshot" do turno. Fire-and-forget.
 */
export const ingestUnifiedMemory = async (payload: UnifiedIngestPayload) => {
  try {
    // Adapter: Converte o formato do Frontend (GraphEdge: source/target) 
    // para o formato da API (subject/object)
    const apiGraphData = payload.graphData.map(edge => ({
      subject: edge.source,
      relation: edge.relation,
      object: edge.target,
      properties: edge.properties
    }));

    const apiPayload = {
      ...payload,
      graphData: apiGraphData
    };

    await apiClient.post('/ingest/unified', apiPayload);
  } catch (error: any) {
    // Diferencia erro de conexão (Offline) de erro de aplicação (Bug/400/500)
    const isNetworkError = error.message && (
        error.message.includes('Failed to fetch') || 
        error.message.includes('NetworkError') ||
        error.message.includes('Falha na conexão')
    );

    if (isNetworkError) {
        console.debug("Backend offline ou inacessível. Ingestão de memória ignorada.");
    } else {
        // Se não for erro de rede, é um erro que o backend retornou (ex: 422, 500)
        console.warn("[Memory Ingest] Falha na API:", error.message || error);
    }
  }
};

/**
 * Busca memórias semânticas (ChromaDB).
 */
export const retrieveContext = async (query: string, universeId: string, userId: string): Promise<string[]> => {
  try {
    const data = await apiClient.post<{ documents: string[] }>('/query/vector', { 
        query, 
        universeId, 
        userId 
    });
    return data.documents || [];
  } catch (error) {
    return []; 
  }
};

/**
 * Busca relacionamentos no Grafo (Neo4j).
 * O Backend retorna { subject, relation, object }, precisamos mapear para { source, target } se necessário,
 * ou o tipo GraphEdge já deve ser compatível.
 */
export const retrieveGraphContext = async (entityName: string, universeId: string, userId: string): Promise<GraphEdge[]> => {
  try {
    // O endpoint retorna arestas. Assumindo que o backend retorna { subject, relation, object }.
    // Precisamos adaptar a resposta para GraphEdge (source, relation, target).
    const data = await apiClient.post<{ edges: any[] }>('/query/graph', { 
        entity: entityName, 
        universeId, 
        userId, 
        depth: 1 
    });

    if (!data.edges) return [];

    return data.edges.map((e: any) => ({
      source: e.subject || e.source,
      target: e.object || e.target,
      relation: e.relation,
      properties: e.properties
    }));
  } catch (error) {
    return [];
  }
};

import { UniverseTemplate, CharacterTemplate, AdventureRecord, GraphEdge } from "../../types";
import { apiClient } from "./core";

// --- Helpers de Sanitização (DTOs) ---
// Garante que o objeto enviado ao backend tenha TODOS os campos esperados,
// convertendo undefined para defaults seguros ([], "", null) e datas para ISO String.

const sanitizeUniverse = (u: UniverseTemplate) => ({
    id: u.id,
    userId: u.userId,
    name: u.name,
    description: u.description || "",
    genre: u.genre,
    image: u.image || null,

    // Arrays: Garante [] ao invés de undefined
    physics: u.physics || [],
    knownTruths: u.knownTruths || [],
    chronicles: u.chronicles || [],
    champions: u.champions || [],
    worlds: u.worlds || [],

    // Enums e Strings Opcionais
    structure: u.structure || 'singular_world',
    navigationMethod: u.navigationMethod || 'physical',
    magicSystem: u.magicSystem || "",
    cosmology: u.cosmology || "",

    // Data: Garante ISO String (Python prefere ISO a Timestamp numérico)
    createdAt: new Date(u.createdAt || Date.now()).toISOString()
});

const sanitizeCharacter = (c: CharacterTemplate) => ({
    id: c.id,
    userId: c.userId,
    name: c.name,
    description: c.description || "",
    archetype: c.archetype,
    image: c.image || null,
    stats: c.stats || {},
    adventuresPlayed: c.adventuresPlayed || 0,
    createdAt: new Date(c.createdAt || Date.now()).toISOString()
});

const sanitizeAdventure = (a: AdventureRecord) => ({
    id: a.id,
    userId: a.userId,
    universeId: a.universeId,
    characterId: a.characterId,
    name: a.name,
    description: a.description || "",
    currentStep: a.currentStep || "",

    // Legacy fields (Garante string vazia se faltar)
    characterName: a.characterName || "",
    universeName: a.universeName || "",
    universeGenre: a.universeGenre || "",
    lastLocation: a.lastLocation || "",

    startDate: new Date(a.startDate || Date.now()).toISOString(),
    createdAt: new Date(a.createdAt || Date.now()).toISOString()
});

// --- Endpoints ---

export const fetchUserLibrary = async (userId: string) => {
  try {
    return await apiClient.get<any>(`/library/${userId}`);
  } catch (error) {
    console.warn("Offline: Não foi possível baixar a biblioteca do servidor.");
    return null;
  }
};

export const syncUniverse = async (userId: string, universe: UniverseTemplate) => {
  try {
    const data = sanitizeUniverse({ ...universe, userId });

    // [NOVO] Graph Context: Cria o nó do Universo imediatamente no Neo4j
    // Adaptado para usar 'subject' e 'object' conforme esperado pela API
    const payload = {
        ...data,
        graphContext: [
            { subject: universe.name, relation: "HAS_GENRE", object: universe.genre },
            { subject: universe.name, relation: "TYPE_OF", object: "Universe" }
        ]
    };
    await apiClient.post('/library/universe', payload);
  } catch (e) { 
    console.warn("Sync Universe failed", e); 
  }
};

export const syncCharacter = async (userId: string, character: CharacterTemplate) => {
  try {
    const data = sanitizeCharacter({ ...character, userId });

    // [NOVO] Graph Context: Garante que o nó do Personagem exista antes do jogo começar
    // Adaptado para usar 'subject' e 'object' conforme esperado pela API
    const payload = {
        ...data,
        graphContext: [
            { subject: character.name, relation: "IS_A", object: character.archetype },
            { subject: character.name, relation: "TYPE_OF", object: "Character" }
            // O Backend deve ligar User -> CREATED -> Character baseado no userId do payload
        ]
    };
    await apiClient.post('/library/character', payload);
  } catch (e) { 
    console.warn("Sync Character failed", e); 
  }
};

export const syncAdventureMetadata = async (userId: string, adventure: AdventureRecord) => {
  try {
    const data = sanitizeAdventure({ ...adventure, userId });

    // [NOVO] Graph Context: Resolve o erro de log "relationship type PLAYS does not exist"
    // Adaptado para usar 'subject' e 'object' conforme esperado pela API
    const payload = {
        ...data,
        graphContext: [
             { subject: userId, relation: "PLAYS", object: adventure.id }, // O Backend deve tratar 'userId' como lookup do nó User
             { subject: adventure.id, relation: "OCCURS_IN", object: adventure.universeName },
             { subject: adventure.id, relation: "STARRING", object: adventure.characterName }
        ]
    };
    await apiClient.post('/library/adventure', payload);
  } catch (e) { 
    console.warn("Sync Adventure failed", e); 
  }
};

